from pathlib import Path

ACTIONS = Path("app/(portal)/store/actions.ts")
BUTTON = Path("components/store/store-paddle-purchase-button.tsx")

actions = ACTIONS.read_text(encoding="utf-8")

old_state = 'export type StorePaddleState = {\n  ok: boolean;\n  error: string | null;\n  checkoutUrl: string | null;\n};'
new_state = 'export type StorePaddleState = {\n  ok: boolean;\n  error: string | null;\n  checkoutUrl: string | null;\n  transactionId: string | null;\n};'
if old_state not in actions: raise SystemExit("Could not find StorePaddleState block.")
actions = actions.replace(old_state, new_state, 1)

repls = [
    ('return { ok: false, error: "Store product is missing.", checkoutUrl: null };', 'return { ok: false, error: "Store product is missing.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: "Paddle is not configured yet.", checkoutUrl: null };', 'return { ok: false, error: "Paddle is not configured yet.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: "You must be signed in.", checkoutUrl: null };', 'return { ok: false, error: "You must be signed in.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: characterResult.error?.message ?? "Character not found.", checkoutUrl: null };', 'return { ok: false, error: characterResult.error?.message ?? "Character not found.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: productResult.error?.message ?? "This Store product is not available.", checkoutUrl: null };', 'return { ok: false, error: productResult.error?.message ?? "This Store product is not available.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: priceResult.error?.message ?? "This product does not have an active Paddle price.", checkoutUrl: null };', 'return { ok: false, error: priceResult.error?.message ?? "This product does not have an active Paddle price.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: grantsResult.error?.message ?? "This Store product has no fulfilment grants.", checkoutUrl: null };', 'return { ok: false, error: grantsResult.error?.message ?? "This Store product has no fulfilment grants.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: orderError?.message ?? "Unable to create Store order.", checkoutUrl: null };', 'return { ok: false, error: orderError?.message ?? "Unable to create Store order.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: itemError?.message ?? "Unable to create Store order item.", checkoutUrl: null };', 'return { ok: false, error: itemError?.message ?? "Unable to create Store order item.", checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: snapshotError.message, checkoutUrl: null };', 'return { ok: false, error: snapshotError.message, checkoutUrl: null, transactionId: null };'),
    ('return { ok: false, error: linkError.message, checkoutUrl: null };', 'return { ok: false, error: linkError.message, checkoutUrl: null, transactionId: null };'),
]
for old, new in repls:
    actions = actions.replace(old, new)

old_failure = '    return {\n      ok: false,\n      error: payload?.error?.detail ?? "Paddle could not create the checkout.",\n      checkoutUrl: null,\n    };'
new_failure = '    return {\n      ok: false,\n      error: payload?.error?.detail ?? "Paddle could not create the checkout.",\n      checkoutUrl: null,\n      transactionId: null,\n    };'
if old_failure not in actions: raise SystemExit("Could not find Paddle failure return.")
actions = actions.replace(old_failure, new_failure, 1)

old_success = '  return { ok: true, error: null, checkoutUrl: payload.data.checkout.url };'
new_success = '  return {\n    ok: true,\n    error: null,\n    checkoutUrl: payload.data.checkout.url,\n    transactionId: payload.data.id,\n  };'
if old_success not in actions: raise SystemExit("Could not find Paddle success return.")
actions = actions.replace(old_success, new_success, 1)

ACTIONS.write_text(actions, encoding="utf-8")
BUTTON.write_text('"use client";\n\nimport { useActionState, useEffect, useRef, useState } from "react";\n\nimport {\n  startStorePaddleCheckout,\n  type StorePaddleState,\n} from "@/app/(portal)/store/actions";\n\ndeclare global {\n  interface Window {\n    Paddle?: {\n      Environment: {\n        set(environment: "sandbox" | "production"): void;\n      };\n      Initialize(options: { token: string }): void;\n      Checkout: {\n        open(options: { transactionId: string }): void;\n      };\n    };\n  }\n}\n\nconst initialState: StorePaddleState = {\n  ok: false,\n  error: null,\n  checkoutUrl: null,\n  transactionId: null,\n};\n\nlet paddleInitializationPromise: Promise<void> | null = null;\n\nfunction loadPaddle(): Promise<void> {\n  if (paddleInitializationPromise) return paddleInitializationPromise;\n\n  paddleInitializationPromise = new Promise((resolve, reject) => {\n    const token = process.env.NEXT_PUBLIC_PADDLE_CLIENT_TOKEN?.trim();\n\n    if (!token) {\n      reject(new Error("Paddle client-side token is not configured."));\n      return;\n    }\n\n    const initialize = () => {\n      if (!window.Paddle) {\n        reject(new Error("Paddle.js did not load."));\n        return;\n      }\n\n      try {\n        if (token.startsWith("test_")) {\n          window.Paddle.Environment.set("sandbox");\n        }\n\n        window.Paddle.Initialize({ token });\n        resolve();\n      } catch (error) {\n        reject(\n          error instanceof Error\n            ? error\n            : new Error("Paddle could not initialize."),\n        );\n      }\n    };\n\n    if (window.Paddle) {\n      initialize();\n      return;\n    }\n\n    const src = "https://cdn.paddle.com/paddle/v2/paddle.js";\n    const existing =\n      document.querySelector<HTMLScriptElement>(`script[src="${src}"]`);\n\n    if (existing) {\n      existing.addEventListener("load", initialize, { once: true });\n      existing.addEventListener(\n        "error",\n        () => reject(new Error("Paddle.js could not be loaded.")),\n        { once: true },\n      );\n      return;\n    }\n\n    const script = document.createElement("script");\n    script.src = src;\n    script.async = true;\n    script.addEventListener("load", initialize, { once: true });\n    script.addEventListener(\n      "error",\n      () => reject(new Error("Paddle.js could not be loaded.")),\n      { once: true },\n    );\n    document.head.appendChild(script);\n  });\n\n  return paddleInitializationPromise;\n}\n\nexport function StorePaddlePurchaseButton({\n  productId,\n  label,\n}: {\n  productId: string;\n  label: string;\n}) {\n  const [state, action, pending] = useActionState(\n    startStorePaddleCheckout,\n    initialState,\n  );\n  const [clientError, setClientError] = useState<string | null>(null);\n  const openedTransactionRef = useRef<string | null>(null);\n\n  useEffect(() => {\n    if (!state.ok || !state.transactionId) return;\n    if (openedTransactionRef.current === state.transactionId) return;\n\n    openedTransactionRef.current = state.transactionId;\n    setClientError(null);\n\n    void loadPaddle()\n      .then(() => {\n        if (!window.Paddle) {\n          throw new Error("Paddle.js did not initialize.");\n        }\n\n        window.Paddle.Checkout.open({\n          transactionId: state.transactionId!,\n        });\n      })\n      .catch((error) => {\n        openedTransactionRef.current = null;\n        setClientError(\n          error instanceof Error\n            ? error.message\n            : "Paddle checkout could not be opened.",\n        );\n      });\n  }, [state.ok, state.transactionId]);\n\n  return (\n    <form action={action} className="mt-2">\n      <input type="hidden" name="productId" value={productId} />\n\n      <button\n        type="submit"\n        disabled={pending}\n        className="w-full border border-[rgb(var(--sep-colour-987344))]/70 bg-[rgb(var(--sep-colour-2a1d12))] px-3 py-2 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-efd9aa))] transition hover:border-[rgb(var(--sep-colour-b78b50))] disabled:cursor-wait disabled:opacity-55"\n      >\n        {pending ? "Opening checkout..." : `Buy for ${label}`}\n      </button>\n\n      {state.error || clientError ? (\n        <p className="mt-2 text-[9px] leading-4 text-red-300">\n          {state.error ?? clientError}\n        </p>\n      ) : null}\n    </form>\n  );\n}\n', encoding="utf-8")
print("Patched Paddle checkout to use Paddle.js overlay checkout.")
